/*
 * A367295  Numbers k such that 6 is the first digit of 2^k.
 * https://oeis.org/A367295
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = k where k is the n-th integer such that the first * digit
 *            of 2^k is 6 (i.e. the fractional part of k*log10(2) lies in *
 *            [log10(6), log10(7)). The sequence is generated by scanning k *
 *            sequentially and collecting those that satisfy the condition
 * Range:     u8 n <= 17, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

/* Local constants, accurate to 20+ decimal digits (80‑bit long double). */
static const long double LOG10_2 = 0.3010299956639811952137388947244930L;
static const long double LOG10_6 = 0.7781512503836436325087667979796120L;
static const long double LOG10_7 = 0.8450980400142568264031731511029460L;

/* Static cache of computed sequence terms. */
static idx_t  next_k = 1;          /* next k to examine                    */
static long double frac = 0.0L;    /* fractional part of k*log10(2)       */
static size_t  cache_len = 0;      /* number of terms stored in cache     */
static seq_t *cache = NULL;        /* pointer to dynamic array of terms   */
static size_t  cache_cap = 0;      /* current capacity of cache array     */

/* Grow the cache array to accommodate at least 'n' elements.  */
static void ensure_cache(size_t n)
{
    if (cache_cap == 0) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else if (n > cache_cap) {
        while (n > cache_cap)
            cache_cap <<= 1;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    /* No meaningful result for n < 1; behaviour is unspecified. */
    if (n == 0)
        return 0;

    /* Ensure the cache has at least n terms. */
    if (cache_len < (size_t)n) {
        ensure_cache(n);
        for (; cache_len < (size_t)n; ++next_k) {
            /* Advance fractional part: f_{k+1} = f_k + log10(2) (mod 1) */
            frac += LOG10_2;
            if (frac >= 1.0L) {
                /* frac < 2, so integer part is either 0 or 1 */
                frac -= (long double)((unsigned long long)frac);
            }
            /* Check if first digit of 2^k is 6. */
            if (frac >= LOG10_6 && frac < LOG10_7) {
                cache[cache_len++] = (seq_t)next_k;
            }
        }
    }
    return cache[n - 1];
}
